from pathlib import Path
import json,hashlib,re,shutil
root=Path('/home/aron/Projects/ascencio/artifacts/skill-authoring-update');review=root/'reviews';cfg=json.loads((review/'config.json').read_text());expected=json.loads((root/'authored-source-hashes.json').read_text())
def hashes(p):return {str(f.relative_to(p)):hashlib.sha256(f.read_bytes()).hexdigest() for f in sorted(p.rglob('*')) if f.is_file()}
verification={s:{'matches':hashes(Path(s))==pins,'expected':pins,'actual':hashes(Path(s))} for s,pins in expected.items()}
(review/'final-source-verification.json').write_text(json.dumps(verification,indent=2)+'\n')
summary={};docs=[]
for key,item in cfg.items():
 out=Path(item['artifacts']); rows=[]
 for i in range(1,6):
  d=out/f'iteration-{i:02}';count=json.loads((d/'counts.json').read_text());check=json.loads((d/'checks.json').read_text())
  assert not check['missing_local_references'] and check['literal_fenced_blocks_identical'] and check['executables_identical'] and check['model_defaults_present']
  assert (d/'comparison.md').exists() and (d/'deletion-audit.md').exists() and (d/'reviewed-package').exists()
  rs=sorted(d.glob('*reviewer-*.md'));assert len(rs)==(6 if key=='refine' and i==1 else 3)
  for p in rs:assert len(re.findall(r'^## [1-8]\. ',p.read_text(),re.M))==8,p
  docs+=rs;rows.append({'iteration':i,**count})
 candidate=Path(item['candidate']);(out/'candidate-manifest.json').write_text(json.dumps(hashes(candidate),indent=2)+'\n')
 baseline=rows[0]['input']['instructional_characters'];final=rows[-1]['candidate']['instructional_characters'];summary[key]={'baseline':baseline,'final':final,'change':final-baseline,'reduction_percent':round((baseline-final)/baseline*100,3),'physical_bytes':rows[-1]['candidate']['physical_bytes'],'iterations':rows,'candidate':item['candidate'],'source':item['source'],'reviewer_assignments':18 if key=='refine' else 15}
 assert hashes(candidate)==hashes(out/'iteration-05'/'reviewed-package')
assert len(docs)==48
(review/'summary.json').write_text(json.dumps({'review_context':'automatic-authoring-review','iterations':15,'reviewer_assignments':len(docs),'model':'gpt-6.1-sol','reasoning_effort':'low','source_hashes_match':all(x['matches'] for x in verification.values()),'packages':summary},indent=2)+'\n')
lines=['# Automatic authoring review index','','Completed five sequential iterations for each of three packages (15 total), with 48 fresh blind explanation assignments launched through supported GPT-6.1 Sol/low controls. Refine iteration 1 needed one additional three-reviewer round to resolve destination interpretation. The unreviewed draft preserved there is not counted as an iteration.','','All three authored-source hashes match their pins at final verification. Sources and historical candidates were never replaced, installed, promoted or committed. These deliverables are separate review candidates.','','| Package | Instructional characters: source → candidate | Final physical bytes | Candidate | Report |','|---|---:|---:|---|---|']
for key,x in summary.items():lines.append(f"| {key} | {x['baseline']:,} → {x['final']:,} | {x['physical_bytes']:,} | [SKILL.md]({x['candidate']}/SKILL.md) | [Report]({review/key/'REPORT.md'}) |")
lines+=['','Counts include every package instructional resource, YAML and instructional code prose; physical bytes include executable-only code. External dependencies remain unchanged and are not claimed as savings. Review artifacts are excluded. No package reaches the 25% aspiration; preservation and readability control the result.','','## Per-iteration evidence','']
for key,x in summary.items():
 lines+= [f'### {key}','','| Iteration | Input characters | Reviewed candidate characters | Physical bytes | Evidence |','|---|---:|---:|---:|---|']
 for row in x['iterations']:
  i=row['iteration'];d=review/key/f'iteration-{i:02}';lines.append(f"| {i} | {row['input']['instructional_characters']:,} | {row['candidate']['instructional_characters']:,} | {row['candidate']['physical_bytes']:,} | [Comparison]({d/'comparison.md'}), [audit]({d/'deletion-audit.md'}), [counts]({d/'counts.json'}), [checks]({d/'checks.json'}) |")
 lines+=['',f"[Original explanation]({review/key/'original-explanation.md'}) · [Behavior inventory]({review/key/'behavior-inventory.md'}) · [Candidate manifest]({review/key/'candidate-manifest.json'})",'']
lines+=['## Validation and limitations','','Local checks passed for filesystem references, explicit defaults and unchanged fenced contracts in every iteration. Bot additionally passed eight candidate-local dispatcher tasks per iteration (40 total) and executable byte-identity checks. Authoring retains all 50 rows in descending strictness order; earlier-row tie precedence and all mandatory behavior remain. Independent deletion audits are separate from reviewer comprehension; no behavioral retirement or resource relocation occurred.','','Read ascencio-tests and ran test:context on Node v26.13.0. No executable implementation change required new application tests. The owner reported the promoted dispatcher’s three existing tests already pass; this review does not re-label that as a newly run test. No gameplay or full suite was run.','','Existing bot runner-document fragment is absent, and the linked document contains overlapping historical policy. Exact current interface/schema must be established before future gameplay dispatch. The preserved canonical command points to the installed skill; in-place execution of the candidate requires verifying intended controller identity. Shared tool guarantees were not re-proven. Reviewer agreement is comprehension evidence, not executable equivalence or measured usability. Launch controls set the requested model/effort; children cannot independently attest backend routing.','','Refine’s only behavioral misunderstanding concerned whether a custom destination could be outside the sibling boundary. Inputs now explicitly says “a sibling folder”, retaining the existing Output rule. Three fresh reviewers confirmed the correction before iteration 1 completed. All later iterations preserve it.','','[Final source verification]('+str(review/'final-source-verification.json')+') · [Accounting method]('+str(review/'accounting-method.md')+') · [Validation selection]('+str(review/'validation-selection.md')+') · [Review settings]('+str(review/'review-settings.json')+') · [Machine-readable summary]('+str(review/'summary.json')+')','']
(review/'INDEX.md').write_text('\n'.join(lines))
